```python
import itertools

def min_payoff(guess, actual):
    """Return the minimum total coins Bob wins over all permutations of actual."""
    min_sum = float('inf')
    for perm in itertools.permutations(actual):
        total = 0
        for g, a in zip(guess, perm):
            if g <= a:
                total += g
        min_sum = min(min_sum, total)
    return min_sum

def valid_actual(actual):
    """Check if there is a pair of boxes with difference exactly 6."""
    a, b, c = actual
    return (b - a == 6) or (c - b == 6) or (c - a == 6)

def main():
    # Generate all guess triples (g1 ≤ g2 ≤ g3)
    guesses = list(itertools.combinations_with_replacement(range(31), 3))

    # Generate all actual triples (a ≤ b ≤ c) summing to 30 and satisfying the difference condition
    actuals = []
    for triple in itertools.combinations_with_replacement(range(31), 3):
        if sum(triple) == 30 and valid_actual(triple):
            actuals.append(triple)

    max_guaranteed = -1
    best_guesses = []
    worst_for_best = {}

    for guess in guesses:
        worst_payoff = float('inf')
        worst_actual = None
        for actual in actuals:
            payoff = min_payoff(guess, actual)
            if payoff < worst_payoff:
                worst_payoff = payoff
                worst_actual = actual
        if worst_payoff > max_guaranteed:
            max_guaranteed = worst_payoff
            best_guesses = [guess]
            worst_for_best = {guess: worst_actual}
        elif worst_payoff == max_guaranteed:
            best_guesses.append(guess)
            worst_for_best[guess] = worst_actual

    print(f"Optimal guaranteed coins: {max_guaranteed}")
    print(f"Minimum money Bob can win: ${max_guaranteed * 1000}")
    print(f"Number of optimal guess triples: {len(best_guesses)}")
    # Display a few optimal guesses and the corresponding worst‑case actual triple
    for guess in best_guesses[:5]:
        print(f"  Guess {guess} → worst actual {worst_for_best[guess]}")

    return max_guaranteed

if __name__ == "__main__":
    main()
```

